        import math

def _dist_abs_list(n, parity):
    # Return sorted list of absolute signed distances from origin for the lines in a given normal-angle class (mod pi)
    # Parity: 0 -> even t, 1 -> odd t; t runs from 1..n//2
    vals = []
    for t in range(1, n//2 + 1):
        if (t % 2) == parity:
            vals.append(math.cos(math.pi * t / n))
    # sort ascending (small to large) for convenience
    vals.sort()
    return vals


def _pair_max_counts(n, parity):
    # Build counts of unordered line-pairs by their max absolute distance, for a normal class of given parity
    # Create signed list: for each abs distance d>0 we have two lines (\u00b1d), for d==0 we have only one
    abs_vals = _dist_abs_list(n, parity)
    signed = []
    eps = 1e-12
    for d in abs_vals:
        if abs(d) < eps:
            signed.append(0.0)
        else:
            signed.append(-d)
            signed.append(+d)
    # Enumerate unordered pairs
    counts = {}
    m = len(signed)
    for i in range(m):
        for j in range(i+1, m):
            mx = max(abs(signed[i]), abs(signed[j]))
            # use rounded key to stabilize float bins
            key = round(mx, 12)
            counts[key] = counts.get(key, 0) + 1
    return counts


def _pair_max_counts_by_k(n, parity):
    # For odd parity classes, classify pairs by number of side-lines used (k in {0,1,2}) and count by max
    # For even parity, there are no side-lines (returns only k=0)
    abs_vals = _dist_abs_list(n, parity)
    eps = 1e-12
    # side distance exists iff parity==1 (odd) and t=1 is present => d_side = cos(pi/n)
    d_side = math.cos(math.pi / n)
    signed = []
    flags = []  # is_side for each line
    for d in abs_vals:
        if abs(d) < eps:
            signed.append(0.0)
            flags.append(False)
        else:
            signed.append(-d)
            flags.append(abs(d - d_side) < 1e-12 and parity == 1)
            signed.append(+d)
            flags.append(abs(d - d_side) < 1e-12 and parity == 1)
    counts_by_k = {0: {}, 1: {}, 2: {}}
    m = len(signed)
    for i in range(m):
        for j in range(i+1, m):
            k_used = (1 if flags[i] else 0) + (1 if flags[j] else 0)
            if k_used > 2:
                k_used = 2
            mx = max(abs(signed[i]), abs(signed[j]))
            key = round(mx, 12)
            counts_by_k[k_used][key] = counts_by_k[k_used].get(key, 0) + 1
    # If parity==0, ensure only k=0 present
    if parity == 0:
        return {0: counts_by_k[0], 1: {}, 2: {}}
    return counts_by_k


def _sum_rectangles(countsA, countsB, limit_sq=1.0):
    # Sum over pairs of maxima where a^2 + b^2 <= limit_sq
    total = 0
    for a_key, a_cnt in countsA.items():
        a = float(a_key)
        a2 = a * a
        for b_key, b_cnt in countsB.items():
            b = float(b_key)
            if a2 + b*b <= limit_sq + 1e-12:
                total += a_cnt * b_cnt
    return total


def _count_for_pair(n, parity, min_side_count):
    # parity is for c in [0..n//2-1], pair with c' = c + n//2 has same parity
    if min_side_count >= 1:
        # only odd parity contributes (has side-lines)
        if parity == 0:
            return 0
        # odd-odd pair
        counts_all = _pair_max_counts(n, parity)
        byk = _pair_max_counts_by_k(n, parity)
        counts_no_side = byk[0]
        total_all = _sum_rectangles(counts_all, counts_all)
        if min_side_count == 1:
            total_no_side = _sum_rectangles(counts_no_side, counts_no_side)
            return total_all - total_no_side
        else:  # min_side_count == 2
            total_zero = _sum_rectangles(counts_no_side, counts_no_side)
            # exactly one side overall: one side in A, none in B OR none in A, one in B
            counts_one = byk[1]
            total_one = 2 * _sum_rectangles(counts_one, counts_no_side)
            return total_all - total_zero - total_one
    else:
        # min_side_count == 0: all admissible rectangles (not used in this generator)
        counts_all = _pair_max_counts(n, parity)
        return _sum_rectangles(counts_all, counts_all)


def _total_count(n, min_side_count):
    # Sum over unordered perpendicular normal-angle pairs: c in 0..n//2-1 paired with c' = c + n//2
    total = 0
    for c in range(0, n//2):
        parity = c % 2
        total += _count_for_pair(n, parity, min_side_count)
    return total


def generator(rng):
    # Choose n divisible by 4, not too small; choose min_side_count in {1,2}
    candidates_n = [n for n in range(12, 76, 4)]
    rng.shuffle(candidates_n)
    for _ in range(100):
        n = rng.choice(candidates_n)
        min_side_count = rng.choice([1, 2])
        ans = _total_count(n, min_side_count)
        # Ensure nontrivial and valid
        if ans > 0 and ans % 1 == 0 and ans >= (n // 4):
            return {'n_sides': n, 'min_side_count': min_side_count}
    # Fallback deterministic if random fails
    n = 12
    min_side_count = 2
    return {'n_sides': n, 'min_side_count': min_side_count}

